CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Permissions" (
    "PermissionId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PermissionCode" character varying(100) NOT NULL,
    "PermissionName" character varying(150) NOT NULL,
    "Module" character varying(100) NOT NULL,
    "Description" character varying(255),
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Permissions" PRIMARY KEY ("PermissionId")
);

CREATE TABLE "Roles" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Description" character varying(255),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "UpdatedAt" timestamptz,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);

CREATE TABLE "SystemSettings" (
    "SettingKey" character varying(100) NOT NULL,
    "SettingValue" character varying(500) NOT NULL,
    "Description" character varying(500),
    "UpdatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "UpdatedByUserId" bigint,
    CONSTRAINT "PK_SystemSettings" PRIMARY KEY ("SettingKey")
);

CREATE TABLE "Users" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "DisplayName" character varying(150) NOT NULL,
    "BirthDate" date,
    "IsEmailVerified" boolean NOT NULL DEFAULT FALSE,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "UpdatedAt" timestamptz,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "RoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" bigint NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_RoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RoleClaims_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "RolePermissions" (
    "RoleId" bigint NOT NULL,
    "PermissionId" integer NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_RolePermissions" PRIMARY KEY ("RoleId", "PermissionId"),
    CONSTRAINT "FK_RolePermissions_Permissions_PermissionId" FOREIGN KEY ("PermissionId") REFERENCES "Permissions" ("PermissionId") ON DELETE CASCADE,
    CONSTRAINT "FK_RolePermissions_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AuditLogs" (
    "AuditLogId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint,
    "Action" character varying(50) NOT NULL,
    "EntityType" character varying(100) NOT NULL,
    "EntityId" character varying(100),
    "OccurredAt" timestamptz NOT NULL DEFAULT (NOW()),
    "DetailsJson" text,
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("AuditLogId"),
    CONSTRAINT "FK_AuditLogs_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "BankAccounts" (
    "BankAccountId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "BankCode" character varying(30),
    "BankName" character varying(100) NOT NULL,
    "AccountName" character varying(100) NOT NULL,
    "AccountNumberMasked" character varying(30),
    "AccountType" character varying(30) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "IsDeleted" boolean NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_BankAccounts" PRIMARY KEY ("BankAccountId"),
    CONSTRAINT "FK_BankAccounts_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Categories" (
    "CategoryId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint,
    "CategoryName" character varying(100) NOT NULL,
    "CategoryType" character varying(20) NOT NULL,
    "Icon" character varying(100),
    "Color" character varying(20),
    "SortOrder" integer NOT NULL DEFAULT 0,
    "IsSystem" boolean NOT NULL DEFAULT FALSE,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Categories" PRIMARY KEY ("CategoryId"),
    CONSTRAINT "FK_Categories_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CreditCards" (
    "CreditCardId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "BankName" character varying(100) NOT NULL,
    "CardName" character varying(100) NOT NULL,
    "CardNumberMasked" character varying(30),
    "BillingDay" smallint,
    "PaymentDueDay" smallint,
    "CreditLimit" numeric(18,2),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_CreditCards" PRIMARY KEY ("CreditCardId"),
    CONSTRAINT "FK_CreditCards_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ImportJobs" (
    "ImportJobId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "ImportType" character varying(30) NOT NULL,
    "FileName" character varying(260),
    "Status" character varying(20) NOT NULL DEFAULT 'Pending',
    "TotalRecords" integer NOT NULL DEFAULT 0,
    "ImportedRecords" integer NOT NULL DEFAULT 0,
    "DuplicateRecords" integer NOT NULL DEFAULT 0,
    "ErrorMessage" character varying(2000),
    "StartedAt" timestamptz,
    "CompletedAt" timestamptz,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_ImportJobs" PRIMARY KEY ("ImportJobId"),
    CONSTRAINT "FK_ImportJobs_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Notifications" (
    "NotificationId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "NotificationType" character varying(50) NOT NULL,
    "Title" character varying(200) NOT NULL,
    "Message" character varying(1000) NOT NULL,
    "Channel" character varying(20) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "RelatedEntityType" character varying(50),
    "RelatedEntityId" bigint,
    "SentAt" timestamptz,
    "ReadAt" timestamptz,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Notifications" PRIMARY KEY ("NotificationId"),
    CONSTRAINT "FK_Notifications_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Tags" (
    "TagId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "TagName" character varying(50) NOT NULL,
    "Color" character varying(20),
    "SortOrder" integer NOT NULL DEFAULT 0,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Tags" PRIMARY KEY ("TagId"),
    CONSTRAINT "FK_Tags_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_UserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UserClaims_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" bigint NOT NULL,
    CONSTRAINT "PK_UserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_UserLogins_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserRefreshTokens" (
    "RefreshTokenId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "TokenHash" character varying(128) NOT NULL,
    "ExpiresAt" timestamptz NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "CreatedByIp" character varying(45),
    "UserAgent" character varying(255),
    "RevokedAt" timestamptz,
    "RevokedByIp" character varying(45),
    "ReplacedByTokenHash" character varying(128),
    "ReasonRevoked" character varying(100),
    CONSTRAINT "PK_UserRefreshTokens" PRIMARY KEY ("RefreshTokenId"),
    CONSTRAINT "FK_UserRefreshTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserRoles" (
    "UserId" bigint NOT NULL,
    "RoleId" bigint NOT NULL,
    "AssignedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_UserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_UserRoles_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserRoles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserSettings" (
    "UserId" bigint NOT NULL,
    "Theme" character varying(10) NOT NULL DEFAULT 'Light',
    "CurrencyCode" character varying(3) NOT NULL DEFAULT 'THB',
    "Locale" character varying(10) NOT NULL DEFAULT 'th-TH',
    "EmailBudgetAlertsEnabled" boolean NOT NULL DEFAULT TRUE,
    "UpdatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_UserSettings" PRIMARY KEY ("UserId"),
    CONSTRAINT "FK_UserSettings_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserTokens" (
    "UserId" bigint NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_UserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_UserTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "TransferGroups" (
    "TransferGroupId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "FromBankAccountId" bigint NOT NULL,
    "ToBankAccountId" bigint NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "TransferDate" timestamptz NOT NULL,
    "Reference" character varying(150),
    "Status" character varying(20) NOT NULL DEFAULT 'Pending',
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_TransferGroups" PRIMARY KEY ("TransferGroupId"),
    CONSTRAINT "FK_TransferGroups_BankAccounts_FromBankAccountId" FOREIGN KEY ("FromBankAccountId") REFERENCES "BankAccounts" ("BankAccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_TransferGroups_BankAccounts_ToBankAccountId" FOREIGN KEY ("ToBankAccountId") REFERENCES "BankAccounts" ("BankAccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_TransferGroups_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CategoryRules" (
    "CategoryRuleId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint,
    "RuleName" character varying(150) NOT NULL,
    "MatchType" character varying(30) NOT NULL,
    "MatchPattern" character varying(300) NOT NULL,
    "CategoryId" bigint NOT NULL,
    "Priority" integer NOT NULL DEFAULT 100,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "UpdatedAt" timestamptz,
    CONSTRAINT "PK_CategoryRules" PRIMARY KEY ("CategoryRuleId"),
    CONSTRAINT "FK_CategoryRules_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("CategoryId") ON DELETE RESTRICT,
    CONSTRAINT "FK_CategoryRules_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Merchants" (
    "MerchantId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MerchantName" character varying(200) NOT NULL,
    "NormalizedName" character varying(200) NOT NULL,
    "DefaultCategoryId" bigint,
    "BankOrProvider" character varying(100),
    "IsVerified" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Merchants" PRIMARY KEY ("MerchantId"),
    CONSTRAINT "FK_Merchants_Categories_DefaultCategoryId" FOREIGN KEY ("DefaultCategoryId") REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL
);

CREATE TABLE "RecurringTransactions" (
    "RecurringTransactionId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "TransactionType" character varying(20) NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Description" character varying(500),
    "CategoryId" bigint,
    "Frequency" character varying(20) NOT NULL,
    "IntervalValue" integer NOT NULL DEFAULT 1,
    "StartDate" date NOT NULL,
    "EndDate" date,
    "NextRunAt" timestamptz NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_RecurringTransactions" PRIMARY KEY ("RecurringTransactionId"),
    CONSTRAINT "FK_RecurringTransactions_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL,
    CONSTRAINT "FK_RecurringTransactions_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CreditCardStatements" (
    "StatementId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CreditCardId" bigint NOT NULL,
    "ImportJobId" bigint,
    "StatementPeriodStart" date NOT NULL,
    "StatementPeriodEnd" date NOT NULL,
    "StatementDate" date NOT NULL,
    "PaymentDueDate" date,
    "PreviousBalance" numeric(18,2) NOT NULL DEFAULT 0.0,
    "PurchaseAmount" numeric(18,2) NOT NULL DEFAULT 0.0,
    "InstallmentAmount" numeric(18,2) NOT NULL DEFAULT 0.0,
    "InterestAmount" numeric(18,2) NOT NULL DEFAULT 0.0,
    "CashbackAmount" numeric(18,2) NOT NULL DEFAULT 0.0,
    "PaymentAmount" numeric(18,2) NOT NULL DEFAULT 0.0,
    "TotalDue" numeric(18,2) NOT NULL,
    "Status" character varying(20) NOT NULL DEFAULT 'Imported',
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_CreditCardStatements" PRIMARY KEY ("StatementId"),
    CONSTRAINT "FK_CreditCardStatements_CreditCards_CreditCardId" FOREIGN KEY ("CreditCardId") REFERENCES "CreditCards" ("CreditCardId") ON DELETE RESTRICT,
    CONSTRAINT "FK_CreditCardStatements_ImportJobs_ImportJobId" FOREIGN KEY ("ImportJobId") REFERENCES "ImportJobs" ("ImportJobId") ON DELETE SET NULL
);

CREATE TABLE "Budgets" (
    "BudgetId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "BudgetName" character varying(150) NOT NULL,
    "ScopeType" character varying(20) NOT NULL,
    "CategoryId" bigint,
    "TagId" bigint,
    "AmountLimit" numeric(18,2) NOT NULL,
    "PeriodType" character varying(20) NOT NULL,
    "StartDate" date NOT NULL,
    "EndDate" date,
    "AlertThresholdPercent" smallint NOT NULL DEFAULT 80,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Budgets" PRIMARY KEY ("BudgetId"),
    CONSTRAINT "FK_Budgets_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL,
    CONSTRAINT "FK_Budgets_Tags_TagId" FOREIGN KEY ("TagId") REFERENCES "Tags" ("TagId") ON DELETE SET NULL,
    CONSTRAINT "FK_Budgets_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "InstallmentPlans" (
    "InstallmentPlanId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "CreditCardId" bigint NOT NULL,
    "MerchantId" bigint,
    "Description" character varying(300) NOT NULL,
    "PrincipalAmount" numeric(18,2) NOT NULL,
    "InstallmentCount" smallint NOT NULL,
    "InstallmentAmount" numeric(18,2) NOT NULL,
    "InterestRatePercent" numeric(7,4) NOT NULL DEFAULT 0.0,
    "StartDate" date NOT NULL,
    "Status" character varying(20) NOT NULL DEFAULT 'Active',
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_InstallmentPlans" PRIMARY KEY ("InstallmentPlanId"),
    CONSTRAINT "FK_InstallmentPlans_CreditCards_CreditCardId" FOREIGN KEY ("CreditCardId") REFERENCES "CreditCards" ("CreditCardId") ON DELETE RESTRICT,
    CONSTRAINT "FK_InstallmentPlans_Merchants_MerchantId" FOREIGN KEY ("MerchantId") REFERENCES "Merchants" ("MerchantId") ON DELETE SET NULL,
    CONSTRAINT "FK_InstallmentPlans_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SlipImportFiles" (
    "SlipImportFileId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "ImportJobId" bigint,
    "StorageKey" character varying(500) NOT NULL,
    "OriginalFileName" character varying(260) NOT NULL,
    "MimeType" character varying(100) NOT NULL,
    "FileSizeBytes" bigint NOT NULL,
    "BankCode" character varying(30),
    "PayerName" character varying(200),
    "PayeeName" character varying(200),
    "DetectedAmount" numeric(18,2),
    "DetectedAt" timestamptz,
    "TransactionReference" character varying(150),
    "FileHash" character varying(128),
    "ReviewStatus" character varying(20) NOT NULL DEFAULT 'Pending',
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "MerchantId" bigint,
    CONSTRAINT "PK_SlipImportFiles" PRIMARY KEY ("SlipImportFileId"),
    CONSTRAINT "FK_SlipImportFiles_ImportJobs_ImportJobId" FOREIGN KEY ("ImportJobId") REFERENCES "ImportJobs" ("ImportJobId") ON DELETE CASCADE,
    CONSTRAINT "FK_SlipImportFiles_Merchants_MerchantId" FOREIGN KEY ("MerchantId") REFERENCES "Merchants" ("MerchantId"),
    CONSTRAINT "FK_SlipImportFiles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CreditCardStatementItems" (
    "StatementItemId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "StatementId" bigint NOT NULL,
    "TransactionDate" date NOT NULL,
    "Description" character varying(500) NOT NULL,
    "ItemType" character varying(30) NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "MerchantId" bigint,
    "InstallmentPlanId" bigint,
    "TransactionId" bigint,
    "ExternalReference" character varying(150),
    "IsDuplicate" boolean NOT NULL DEFAULT FALSE,
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_CreditCardStatementItems" PRIMARY KEY ("StatementItemId"),
    CONSTRAINT "FK_CreditCardStatementItems_CreditCardStatements_StatementId" FOREIGN KEY ("StatementId") REFERENCES "CreditCardStatements" ("StatementId") ON DELETE CASCADE,
    CONSTRAINT "FK_CreditCardStatementItems_InstallmentPlans_InstallmentPlanId" FOREIGN KEY ("InstallmentPlanId") REFERENCES "InstallmentPlans" ("InstallmentPlanId") ON DELETE SET NULL,
    CONSTRAINT "FK_CreditCardStatementItems_Merchants_MerchantId" FOREIGN KEY ("MerchantId") REFERENCES "Merchants" ("MerchantId") ON DELETE SET NULL
);

CREATE TABLE "Transactions" (
    "TransactionId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "TransactionType" character varying(20) NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "CurrencyCode" character varying(3) NOT NULL DEFAULT 'THB',
    "TransactionDate" timestamptz NOT NULL,
    "Description" character varying(500),
    "CategoryId" bigint,
    "MerchantId" bigint,
    "BankAccountId" bigint,
    "CreditCardId" bigint,
    "SourceType" character varying(30) NOT NULL,
    "ImportJobId" bigint,
    "SlipImportFileId" bigint,
    "StatementItemId" bigint,
    "TransferGroupId" bigint,
    "RecurringTransactionId" bigint,
    "Status" character varying(20) NOT NULL DEFAULT 'Confirmed',
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    "UpdatedAt" timestamptz,
    "InstallmentPlanId" bigint,
    CONSTRAINT "PK_Transactions" PRIMARY KEY ("TransactionId"),
    CONSTRAINT "FK_Transactions_BankAccounts_BankAccountId" FOREIGN KEY ("BankAccountId") REFERENCES "BankAccounts" ("BankAccountId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_CreditCardStatementItems_StatementItemId" FOREIGN KEY ("StatementItemId") REFERENCES "CreditCardStatementItems" ("StatementItemId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_CreditCards_CreditCardId" FOREIGN KEY ("CreditCardId") REFERENCES "CreditCards" ("CreditCardId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_ImportJobs_ImportJobId" FOREIGN KEY ("ImportJobId") REFERENCES "ImportJobs" ("ImportJobId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_InstallmentPlans_InstallmentPlanId" FOREIGN KEY ("InstallmentPlanId") REFERENCES "InstallmentPlans" ("InstallmentPlanId"),
    CONSTRAINT "FK_Transactions_Merchants_MerchantId" FOREIGN KEY ("MerchantId") REFERENCES "Merchants" ("MerchantId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_RecurringTransactions_RecurringTransactionId" FOREIGN KEY ("RecurringTransactionId") REFERENCES "RecurringTransactions" ("RecurringTransactionId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_SlipImportFiles_SlipImportFileId" FOREIGN KEY ("SlipImportFileId") REFERENCES "SlipImportFiles" ("SlipImportFileId") ON DELETE RESTRICT,
    CONSTRAINT "FK_Transactions_TransferGroups_TransferGroupId" FOREIGN KEY ("TransferGroupId") REFERENCES "TransferGroups" ("TransferGroupId") ON DELETE SET NULL,
    CONSTRAINT "FK_Transactions_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "TransactionTags" (
    "TransactionId" bigint NOT NULL,
    "TagId" bigint NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_TransactionTags" PRIMARY KEY ("TransactionId", "TagId"),
    CONSTRAINT "FK_TransactionTags_Tags_TagId" FOREIGN KEY ("TagId") REFERENCES "Tags" ("TagId") ON DELETE CASCADE,
    CONSTRAINT "FK_TransactionTags_Transactions_TransactionId" FOREIGN KEY ("TransactionId") REFERENCES "Transactions" ("TransactionId") ON DELETE CASCADE
);

